import type { KnipConfig } from 'knip'

// Test files are in `ignore` so their imports don't count as "usage", flagging exports used only by test files as unused.
// Tradeoff: dead code & exports within test files won't be detected. See: https://github.com/webpro-nl/knip/issues/1374. This is acceptable
const config: KnipConfig = {
  entry: [
    // Library entry points — match the `exports` field in package.json
    'src/layout.ts',
    'src/rich-inline.ts',
    // Scripts invoked via package.json
    'scripts/**/*.ts',
    // Browser pages and demos — each `pages/**/*.ts` is the target of a `<script type="module" src="…">` in a sibling `.html`
    'pages/**/*.ts',
    // Bundled through the comparison runner's generated candidate entry.
    'tests/wrapping/browser.ts',
    'tests/wrapping/contracts.ts',
    'tests/wrapping/numeric.ts',
  ],
  ignore: [
    '**/*.test.ts', // Exclude tests so their imports don't count as "usage"
  ],
  ignoreDependencies: [
    'tsgolint', // Type-aware checker invoked by `oxlint --type-aware` via oxlint-tsgolint
  ],
  ignoreBinaries: [
    // Used in package.json scripts
    'lsof',
  ],
  // slightly confusing config. We detect dead code just fine
  // this one's just to silence exported types and values that aren't used elsewhere but that are still used within their file
  // yelling on unnecessary exports is a bit noisy so we turn it off
  ignoreExportsUsedInFile: true,
}

export default config

import chrome from '../accuracy/chrome.json'
import safari from '../accuracy/safari.json'
import firefox from '../accuracy/firefox.json'

type Snapshot = {
  total: number
  matchCount: number
  mismatchCount: number
  generatedAt: string
  environments: Array<{ userAgent: string; dpr: number }>
  mismatches: Array<{ id: string; label: string; font: string; width: number; actual: number; predicted: number; diff: number }>
}

function escapeHtml(text: string): string {
  return text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
}

const root = document.getElementById('root')!
for (const [browser, snapshot] of Object.entries<Snapshot>({ chrome, safari, firefox })) {
  const section = document.createElement('section')
  section.innerHTML = `<h2>${browser}</h2>
    <div class="summary"><span class="big">${snapshot.matchCount}/${snapshot.total}</span> match
    <span class="sep">|</span>${snapshot.mismatchCount} mismatches</div>
    <p class="sub">${escapeHtml(snapshot.environments[0]!.userAgent)} · DPR ${snapshot.environments[0]!.dpr}<br>${escapeHtml(snapshot.generatedAt)}</p>`
  if (snapshot.mismatches.length > 0) {
    section.innerHTML += `<table><tr><th>Case</th><th>Font</th><th>Width</th><th>Actual</th><th>Predicted</th></tr>${snapshot.mismatches.map(row =>
      `<tr><td class="text">${escapeHtml(row.label)}<br>${row.id}</td><td class="text">${escapeHtml(row.font)}</td><td>${row.width}px</td><td>${row.actual}px</td><td>${row.predicted}px</td></tr>`,
    ).join('')}</table>`
  }
  root.append(section)
}

import fontData from '../tests/wrapping/fonts/fonts.json' with { type: 'json' }
import { createBrowserEnvironmentGuard } from '../shared/browser-environment.ts'
import {
  BATCH_WORDS, planWord, predictSite, predictWhole, probeFonts, probeInputs, withinTolerance, wordFeatures,
  type ArabicJoiningProbeReport, type CanvasContextKind, type Measure, type ProbeFont, type ProbeQuery, type ProbeRow, type ProbeWord,
} from '../shared/arabic-joining-probe.ts'
import { loadFonts } from '../tests/wrapping/browser.ts'
import { observeNative, pointLine } from '../tests/wrapping/observe.ts'
import type { NativeObservation, NativeRect } from '../tests/wrapping/types.ts'
import { publishNavigationPhase, publishNavigationReport } from './report-utils.ts'

type Direction = 'ltr' | 'rtl'
type WhiteSpace = 'normal' | 'pre-wrap'
type Threshold = { native: number | null; lineCount: number; firstLineEnd: number; rects: NativeRect[] }

const LINE_HEIGHT = 48
const RECT_EPSILON = 0.00001
const APP_UNITS = 60
const BRACKET_DELTAS = [-0.5, -0.1, -0.02, 0.02, 0.1, 0.5]
const params = new URLSearchParams(location.search)
const requestId = params.get('requestId') ?? ''
const reportEndpoint = params.get('reportEndpoint')
const fontBase = params.get('fontBase')
const fontLabel = params.get('font') ?? 'arial-16'
const batch = Number(params.get('batch') ?? '0')
const limit = Number(params.get('limit') ?? 'Infinity')
const status = document.querySelector<HTMLParagraphElement>('#status')!

// Pretext's offscreen context, plus controls: a connected lang=en canvas and
// offscreen contexts with textRendering or fontKerning set. Each distinct query
// is measured once per page and lists every recipe that needed it.
function createMeasure(font: string): { measure: Measure; queries: Map<string, ProbeQuery> } {
  const canvas = document.createElement('canvas')
  canvas.lang = 'en'
  canvas.hidden = true
  document.body.append(canvas)
  const contexts: Record<CanvasContextKind, OffscreenCanvasRenderingContext2D | CanvasRenderingContext2D> = {
    'offscreen': new OffscreenCanvas(1, 1).getContext('2d')!,
    'connected': canvas.getContext('2d')!,
    'legibility': new OffscreenCanvas(1, 1).getContext('2d')!,
    'kerning-normal': new OffscreenCanvas(1, 1).getContext('2d')!,
    'kerning-none': new OffscreenCanvas(1, 1).getContext('2d')!,
  }
  contexts.legibility.textRendering = 'optimizeLegibility'
  contexts['kerning-normal'].fontKerning = 'normal'
  contexts['kerning-none'].fontKerning = 'none'
  const kinds = Object.keys(contexts) as CanvasContextKind[]
  for (let i = 0; i < kinds.length; i++) contexts[kinds[i]!].font = font
  const queries = new Map<string, ProbeQuery>()
  function measure(recipe: string, context: CanvasContextKind, direction: CanvasDirection, text: string): number {
    const key = `${context}\u0000${direction}\u0000${text}`
    let query = queries.get(key)
    if (query === undefined) {
      const ctx = contexts[context]
      ctx.direction = direction
      const metrics = ctx.measureText(text)
      query = { context, direction: ctx.direction, text, width: metrics.width, left: metrics.actualBoundingBoxLeft, right: metrics.actualBoundingBoxRight, recipes: [] }
      queries.set(key, query)
    }
    if (!query.recipes.includes(recipe)) query.recipes.push(recipe)
    return query.width
  }
  return { measure, queries }
}

function rangeExtent(range: Range): { width: number; rects: NativeRect[] } {
  const list = range.getClientRects()
  const rects: NativeRect[] = []
  let left = Infinity
  let right = -Infinity
  for (let i = 0; i < list.length; i++) {
    const rect = list.item(i)!
    if (rect.width <= RECT_EPSILON || rect.height <= RECT_EPSILON) continue
    rects.push({ x: rect.x, y: rect.y, width: rect.width, height: rect.height })
    left = Math.min(left, rect.x)
    right = Math.max(right, rect.x + rect.width)
  }
  return { width: rects.length === 0 ? 0 : right - left, rects }
}

// Source offsets across the word's text nodes: one node, or one per rich item.
function selectSource(range: Range, element: HTMLElement, start: number, end: number): void {
  const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT)
  let offset = 0
  let started = false
  let ended = false
  for (let node = walker.nextNode(); node !== null; node = walker.nextNode()) {
    const length = (node as Text).length
    if (!started && start < offset + length) {
      range.setStart(node, start - offset)
      started = true
    }
    if (!ended && end <= offset + length) {
      range.setEnd(node, end - offset)
      ended = true
    }
    offset += length
  }
}

// The unmodified word in a fixed-width paragraph: is the head's last visible
// scalar on the first line? Line assignment uses the harness pointLine rule.
function observeHead(word: ProbeWord, font: string, direction: Direction, whiteSpace: WhiteSpace, width: number, offset: number): { fits: boolean | null; native: NativeObservation } {
  const native = observeNative({
    id: 'arabic-joining-probe', family: 'arabic-joining-probe', origins: [], scope: 'research',
    text: word.text, font, lineHeight: LINE_HEIGHT, width, whiteSpace, wordBreak: 'normal', letterSpacing: 0, direction,
  }, 'firefox')
  const lineCount = Math.round(native.lineCount)
  for (let i = native.points.length - 1; i >= 0; i--) {
    const point = native.points[i]!
    if (point.end > offset || !point.rects.some(rect => rect.width > RECT_EPSILON && rect.height > RECT_EPSILON)) continue
    const line = pointLine(point, LINE_HEIGHT, lineCount)
    return { fits: line === null ? null : line === 0, native }
  }
  return { fits: null, native }
}

function firstLineEnd(native: NativeObservation): number {
  const lineCount = Math.round(native.lineCount)
  let end = 0
  for (let i = 0; i < native.points.length; i++) {
    const point = native.points[i]!
    if (pointLine(point, LINE_HEIGHT, lineCount) === 0) end = point.end
  }
  return end
}

function summarize(native: number | null, observation: NativeObservation): Threshold {
  return { native, lineCount: observation.lineCount, firstLineEnd: firstLineEnd(observation), rects: observation.lineRects }
}

// The smallest box width, in app units, whose first line holds the head. Gecko
// never ends a line between a letter and its soft hyphen, so the head reaches
// the first line with its hyphen or inside a longer line. A bracket around the
// expected width saves reflows; the full range is the fallback. A head that
// always fits, such as one letter before an overflowing hyphen, has no threshold.
function searchThreshold(word: ProbeWord, font: string, direction: Direction, whiteSpace: WhiteSpace, offset: number, expected: number, widest: number): Threshold {
  const at = (units: number) => observeHead(word, font, direction, whiteSpace, units / APP_UNITS, offset)
  let lo = Math.max(0, Math.floor(expected * APP_UNITS) - APP_UNITS)
  let hi = Math.ceil(expected * APP_UNITS) + APP_UNITS
  let low = at(lo)
  let high = at(hi)
  if (low.fits !== false || high.fits !== true) {
    lo = 0
    hi = Math.ceil(widest * APP_UNITS) + 10 * APP_UNITS
    low = at(lo)
    high = at(hi)
  }
  if (low.fits !== false || high.fits !== true) return summarize(null, low.fits === false ? high.native : low.native)
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1
    const middle = at(mid)
    if (middle.fits === null) return summarize(null, middle.native)
    if (middle.fits) {
      hi = mid
      high = middle
    } else lo = mid
  }
  return summarize(hi / APP_UNITS, high.native)
}

function measureWord(word: ProbeWord, index: number, probeFont: ProbeFont, direction: Direction, measure: Measure, hyphen: number, rows: ProbeRow[]): void {
  const font = probeFont.font
  const plan = planWord(word)
  // Ground truth: one intact text node (or the rich items) on one line, with
  // Range widths at source offsets. Soft hyphens stay in the source.
  const element = document.createElement('div')
  Object.assign(element.style, {
    position: 'absolute', left: '0', top: '0', margin: '0', padding: '0', border: '0',
    font, lineHeight: `${LINE_HEIGHT}px`, whiteSpace: 'pre', width: 'max-content', direction,
  })
  if (word.parts === undefined) element.textContent = word.text
  else {
    element.replaceChildren(...word.parts.map((part, i) => {
      const span = document.createElement('span')
      span.textContent = part
      if (i > 0 && word.family === 'rich-color') span.style.color = '#b00020'
      return span
    }))
  }
  document.body.append(element)
  const range = document.createRange()
  range.selectNodeContents(element)
  const whole = rangeExtent(range)
  const wholePredictions = predictWhole(plan, measure)
  const trusted = withinTolerance(whole.width - wholePredictions['r1-run']!)
  const predictions: Array<ReturnType<typeof predictSite>> = []
  let wordResidual = 0
  for (let i = 0; i < plan.sites.length; i++) {
    const prediction = predictSite(plan, plan.sites[i]!, measure)
    predictions.push(prediction)
    wordResidual = Math.max(wordResidual, Math.abs(prediction.residual))
  }
  const base = { font: probeFont.label, direction, word: index, trusted, wordResidual }
  rows.push({
    ...base, measure: 'whole', site: 'whole', offset: word.text.length, units: plan.units.length, joins: false,
    native: whole.width, predictions: wholePredictions, residual: null, ...(whole.rects.length > 1 ? { rects: whole.rects } : {}),
  })
  const headWidths: number[] = []
  for (let i = 0; i < plan.sites.length; i++) {
    const site = plan.sites[i]!
    const prediction = predictions[i]!
    const siteBase = { ...base, site: site.kind, offset: site.offset, units: site.units, joins: site.joins, residual: prediction.residual }
    selectSource(range, element, 0, site.offset)
    const head = rangeExtent(range)
    selectSource(range, element, site.offset, word.text.length)
    const tail = rangeExtent(range)
    headWidths.push(head.width)
    rows.push({ ...siteBase, measure: 'head', native: head.width, predictions: prediction.head, ...(head.rects.length > 1 ? { rects: head.rects } : {}) })
    rows.push({ ...siteBase, measure: 'tail', native: tail.width, predictions: prediction.tail, ...(tail.rects.length > 1 ? { rects: tail.rects } : {}) })
  }
  element.remove()

  for (let i = 0; i < plan.sites.length; i++) {
    const site = plan.sites[i]!
    const prediction = predictions[i]!
    const siteBase = { ...base, site: site.kind, offset: site.offset, units: site.units, joins: site.joins, residual: prediction.residual }
    const names = ['isolated', site.kind === 'shy' ? 'r2-head-zwj' : 'r2c-prefix-zwj', 'r2b-grapheme-forms', 'r4-complement']
    if (site.kind === 'shy') {
      // Soft-hyphen thresholds: head plus the U+2010 hyphen Gecko paints.
      const hyphenated: Record<string, number> = {}
      for (let j = 0; j < names.length; j++) hyphenated[names[j]!] = prediction.head[names[j]!]! + hyphen
      const whiteSpaces: WhiteSpace[] = ['normal', 'pre-wrap']
      for (let w = 0; w < whiteSpaces.length; w++) {
        const whiteSpace = whiteSpaces[w]!
        const threshold = searchThreshold(word, font, direction, whiteSpace, site.offset, headWidths[i]! + hyphen, whole.width + hyphen)
        const bracket: NonNullable<ProbeRow['bracket']> = []
        for (let j = 0; j < names.length; j++) {
          for (let d = 0; d < BRACKET_DELTAS.length; d++) {
            const delta = BRACKET_DELTAS[d]!
            const observation = observeHead(word, font, direction, whiteSpace, Math.max(0, hyphenated[names[j]!]! + delta), site.offset)
            bracket.push({ recipe: names[j]!, delta, lineCount: observation.native.lineCount, fits: observation.fits })
          }
        }
        rows.push({
          ...siteBase, measure: whiteSpace === 'normal' ? 'hyphen-normal' : 'hyphen-pre-wrap', native: threshold.native, predictions: hyphenated,
          rects: threshold.rects, lineCount: threshold.lineCount, firstLineEnd: threshold.firstLineEnd, bracket,
        })
      }
    } else if (site.kind === 'grapheme' && site.units >= 2 && !word.text.includes('\u00AD')) {
      // Emergency thresholds: the smallest width whose first line holds `units` graphemes.
      const heads: Record<string, number> = {}
      for (let j = 0; j < names.length; j++) heads[names[j]!] = prediction.head[names[j]!]!
      const threshold = searchThreshold(word, font, direction, 'normal', site.offset, headWidths[i]!, whole.width)
      rows.push({
        ...siteBase, measure: 'emergency', native: threshold.native, predictions: heads,
        rects: threshold.rects, lineCount: threshold.lineCount, firstLineEnd: threshold.firstLineEnd,
      })
    }
  }
}

async function publish(report: ArabicJoiningProbeReport): Promise<void> {
  if (reportEndpoint !== null) {
    publishNavigationPhase('posting', requestId)
    const response = await fetch(reportEndpoint, { method: 'POST', body: JSON.stringify(report) })
    if (!response.ok) throw new Error(`Report POST failed: ${response.status}`)
  }
  publishNavigationReport({ status: report.status, requestId })
}

let environmentGuard: ReturnType<typeof createBrowserEnvironmentGuard> | undefined
try {
  publishNavigationPhase('loading', requestId)
  const probeFont = probeFonts.find(font => font.label === fontLabel)
  if (probeFont === undefined) throw new Error(`Unknown probe font: ${fontLabel}`)
  const faces = fontData.filter(face => face.family === probeFont.fixture)
  if (faces.length > 0 && fontBase === null) throw new Error('Fixture faces need a fontBase URL.')
  await loadFonts(faces.map(face => ({ family: face.family, weight: face.weight, url: `${fontBase}${face.file}`, sha256: face.sha256 })))
  await document.fonts.load(probeFont.font, 'بب')
  environmentGuard = createBrowserEnvironmentGuard('correctness')
  environmentGuard.assertStable()
  const inputs = probeInputs(probeFont)
  const total = Math.min(inputs.length, limit)
  const from = batch * BATCH_WORDS
  const to = Math.min(from + BATCH_WORDS, total)
  if (!Number.isSafeInteger(batch) || batch < 0 || from >= to) throw new Error(`Batch ${batch} is outside ${total} words.`)
  const { measure, queries } = createMeasure(probeFont.font)
  const hyphenRecipes = ['isolated', 'r2-head-zwj', 'r2b-grapheme-forms', 'r4-complement']
  let hyphen = 0
  for (let i = 0; i < hyphenRecipes.length; i++) hyphen = measure(hyphenRecipes[i]!, 'offscreen', 'inherit', '\u2010')
  const hyphens = { u2010: hyphen, minus: measure('isolated', 'offscreen', 'inherit', '-') }
  publishNavigationPhase('measuring', requestId)
  const words: Array<ProbeWord & { index: number; features: string[] }> = []
  const rows: ProbeRow[] = []
  for (let index = from; index < to; index++) {
    const word = inputs[index]!
    words.push({ ...word, index, features: wordFeatures(word.text) })
    measureWord(word, index, probeFont, 'rtl', measure, hyphen, rows)
    measureWord(word, index, probeFont, 'ltr', measure, hyphen, rows)
    environmentGuard.assertStable()
    status.textContent = `${probeFont.label} batch ${batch}: ${index + 1 - from}/${to - from} words`
    // Let display events reach the guard and keep Firefox's slow-script warning away.
    await new Promise<void>(resolve => setTimeout(resolve, 0))
  }
  environmentGuard.assertStable()
  // Range-level TextMetrics would give per-range advances directly; record whether they exist.
  const features = {
    getSelectionRects: 'getSelectionRects' in TextMetrics.prototype,
    getActualBoundingBox: 'getActualBoundingBox' in TextMetrics.prototype,
    getTextClusters: 'getTextClusters' in TextMetrics.prototype,
    textRendering: 'textRendering' in OffscreenCanvasRenderingContext2D.prototype,
    fontKerning: 'fontKerning' in OffscreenCanvasRenderingContext2D.prototype,
  }
  await publish({
    status: 'ready', requestId, environment: environmentGuard.report(), font: probeFont.label, batch, from, to, total,
    hyphens, features, words, rows, queries: Array.from(queries.values()),
  })
  status.textContent = `${probeFont.label} batch ${batch}: ${to - from} words, ${rows.length} rows, ${queries.size} Canvas queries.`
} catch (error) {
  const message = error instanceof Error ? error.message : String(error)
  status.textContent = message
  await publish({ status: 'error', requestId, message, ...(environmentGuard === undefined ? {} : { environment: environmentGuard.report() }) })
} finally {
  environmentGuard?.dispose()
}
